    <tr>
        <td width="175" height="617" rowspan="31">
            <p align="center"><font size="2" color="blue"><a href="com_greeting.php" target="_self"><b>인 사 말</b></a></font></p>
            <p align="center"><font size="2" color="blue"><a href="com_history.php" target="_self"><b>회 사 연 혁</b></a></font></p>
            <p align="center"><font size="2" color="blue"><a href="com_map.php" target="_self"><b>회 사 위 치</b></a></font></p>
